// AWS's x-amz-json-1.1 responses aren't auto-parsed by n8n's HTTP Request
// node -- the whole body lands as a raw string under $json.data (see the
// build-n8n-workflow skill, gotcha #7). Parse it here.
const body = JSON.parse($json.data);
const results = body.FileTransferResults || [];
return [{ json: {
  transferId: $('When clicking "Execute workflow"').first().json.transferId,
  resultCount: results.length,
  allCompleted: results.length > 0 && results.every((r) => r.StatusCode === 'COMPLETED'),
  results,
} }];
